import XCTest
import Foundation
@testable import ZephyrCore

/// Phase 6: sheet lists and CLI publish over the Zephyr-internal tolerant
/// `.dsd` subset (NOT AutoCAD grammar — no authenticated AutoCAD LT
/// sample exists, so every document here is generated by Zephyr's own
/// writer or hand-written against the subset documented on `PublishDSD`).
///
/// Covers the internal round-trip, tolerant unknown-section handling,
/// CLI sheet-list loading (replace + append), the `-PUBLISH` foreground
/// run with CSV log creation, and the `-PUBLISH` prompt flow.
@MainActor
final class DSDPublishTests: XCTestCase {

    // MARK: - Fixtures (generated, no checked-in binaries)

    private func layeredDoc() -> CADDocument {
        let doc = CADDocument()
        doc.importLayersBlocksEntities(layers: [Layer(
            handle: UUID(), name: "0", isVisible: true,
            lineWeight: 0.25, color: .white, lineType: "CONTINUOUS")], blocks: [], entities: [])
        return doc
    }

    private func modelSetup(named name: String) -> CADPlotSettings {
        var ps = CADPlotSettings(
            paperWidthMM: 297, paperHeightMM: 210,
            marginLM: 5, marginBM: 5, marginRM: 5, marginTM: 5,
            plotPaperUnits: 1, plotRotation: 1,
            pageSetupName: name,
            plotConfigName: "DWG To PDF.pc3",
            canonicalMediaName: "ISO_A4_(297.00_x_210.00_MM)",
            plotType: 1, standardScaleType: 0)
        ps.useStandardScale = false
        return ps
    }

    private func layoutSetup(named name: String) -> CADPlotSettings {
        var ps = CADPlotSettings(
            paperWidthMM: 420, paperHeightMM: 297,
            marginLM: 10, marginBM: 10, marginRM: 10, marginTM: 10,
            plotPaperUnits: 1, plotRotation: 1,
            pageSetupName: name,
            plotConfigName: "AutoCAD PDF (High Quality Print).pc3",
            canonicalMediaName: "ISO_full_bleed_A3_(420.00_x_297.00_MM)",
            plotType: 5, standardScaleType: 16)
        ps.useStandardScale = true
        return ps
    }

    private func snapshotDoc() -> CADDocument {
        let doc = layeredDoc()
        let layerID = doc.allLayers.first!.handle
        doc.addEntity(CADEntity(
            layerID: layerID,
            localGeometry: [.line(
                start: Vector3(x: 0, y: 0, z: 0),
                end: Vector3(x: 50, y: 25, z: 0))],
            transform: .identity))
        return doc
    }

    /// Write a two-tab DXF drawing fixture; native settings and named
    /// setups included when given.
    private func writeDrawingFixture(
        modelNative: CADPlotSettings? = nil,
        layoutNative: CADPlotSettings? = nil,
        namedSetups: [CADNamedPageSetup] = []
    ) throws -> URL {
        let modelDoc = layeredDoc()
        modelDoc.plotSettings = modelNative
        let sheetDoc = layeredDoc()
        sheetDoc.plotSettings = layoutNative
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("dsdcli-\(UUID().uuidString).dxf")
        try DXFWriterBridge.export(
            views: [
                DrawingView(name: "Model", kind: .model, document: modelDoc),
                DrawingView(name: "Layout1", kind: .sheet, document: sheetDoc),
            ],
            to: url, namedSetups: namedSetups)
        return url
    }

    private func jobSpec(
        modelPath: String, layoutPath: String, masterPath: String
    ) -> PublishJobSpec {
        let master = PublishSheetEntry(
            sheetName: "Master-Model",
            drawingID: UUID(),
            sourceDwgPath: modelPath,
            tabName: "Model",
            space: .model,
            defaultSetupName: "PDF A4 - Model",
            defaultSetup: modelSetup(named: "PDF A4 - Model"))
        var borrowed = PublishSheetEntry(
            sheetName: "1-Model",
            drawingID: UUID(),
            sourceDwgPath: layoutPath,
            tabName: "Model",
            space: .model)
        borrowed.assignment = PublishSetupAssignment(
            mode: .importedMaster, setupName: "PDF A4 - Model",
            masterDwgPath: masterPath,
            resolvedSetup: modelSetup(named: "PDF A4 - Model"))
        var local = PublishSheetEntry(
            sheetName: "1-Layout1",
            drawingID: borrowed.drawingID,
            sourceDwgPath: layoutPath,
            tabName: "Layout1",
            space: .layout)
        local.assignment = PublishSetupAssignment(
            mode: .namedLocal, setupName: "PDF A3 - Layout",
            resolvedSetup: layoutSetup(named: "PDF A3 - Layout"))
        return PublishJobSpec(
            publishTo: .pdf,
            outputDirectory: "/jobs/out",
            fileType: .singleSheetFiles,
            namingPolicy: .autoName,
            includeLayerInfo: false,
            mergeControl: .mergeLines,
            numberOfCopies: 3,
            includePlotStamp: true,
            publishInBackground: true,
            openInViewerWhenDone: true,
            sheets: [master, borrowed, local])
    }

    // MARK: - Internal round-trip

    func testInternalSubsetRoundTrip() throws {
        let spec = jobSpec(
            modelPath: "/master/Master.dxf", layoutPath: "/jobs/1.dxf",
            masterPath: "/master/Master.dxf")
        let text = PublishDSD.serialize(spec: spec)
        XCTAssertTrue(text.contains("[Job]"))
        XCTAssertTrue(text.contains("[Sheet3]"))
        let parsed = try PublishDSD.parse(text)
        XCTAssertEqual(parsed, PublishDSDJob(spec: spec))
        // The writer is stable: re-serializing the parse reproduces it.
        XCTAssertEqual(PublishDSD.serialize(job: parsed), text)
    }

    // MARK: - Tolerant unknown-section handling

    func testUnknownSectionsAndKeysAreIgnored() throws {
        let text = """
            ; Zephyr publish sheet list
            [PrinterConfig]
            Driver=Anything
            [Sheet2]
            Source=/jobs/1.dxf
            Tab=Layout1
            Space=Layout
            Name=Second
            ExtraKey=ignored
            [sheet1]
            source=/jobs/1.dxf
            tab=Model
            space=Model
            name=First
            assignmode=Default
            [Preview]
            Thumb=1
            [JOB]
            publishto=Bogus
            filetype=Single
            naming=Auto
            mergECONTROL=Merge
            copies=not-a-number
            UnknownOption=7
            """
        let parsed = try PublishDSD.parse(text)
        // Unknown sections never surface; sheets apply in numeric order.
        XCTAssertEqual(parsed.sheets.map(\.sheetName), ["First", "Second"])
        XCTAssertEqual(parsed.sheets.map(\.tabName), ["Model", "Layout1"])
        // Unknown enum values fall back to defaults; bad Copies keeps 1.
        XCTAssertEqual(parsed.publishTo, .plotterNamedInPageSetup)
        XCTAssertEqual(parsed.fileType, .singleSheetFiles)
        XCTAssertEqual(parsed.namingPolicy, .autoName)
        XCTAssertEqual(parsed.mergeControl, .mergeLines)
        XCTAssertEqual(parsed.numberOfCopies, 1)
    }

    func testSheetWithoutTabStillThrows() {
        let text = "[Job]\nPublishTo=PDF\n[Sheet1]\nSource=/jobs/1.dxf\n"
        XCTAssertThrowsError(try PublishDSD.parse(text)) { error in
            guard case .malformedSheet(let section, _) = error as? PublishDSDError else {
                return XCTFail("expected malformedSheet, got \(error)")
            }
            XCTAssertEqual(section, "Sheet1")
        }
    }

    // MARK: - CLI sheet-list loading (replace + append)

    func testCLIListLoadingReplaceAndAppend() throws {
        let masterURL = try writeDrawingFixture(
            modelNative: modelSetup(named: "PDF A4 - Model"),
            layoutNative: layoutSetup(named: "PDF A3 - Layout"),
            namedSetups: [
                CADNamedPageSetup(
                    name: "PDF A4 - Model",
                    settings: modelSetup(named: "PDF A4 - Model"), isModelType: true),
                CADNamedPageSetup(
                    name: "PDF A3 - Layout",
                    settings: layoutSetup(named: "PDF A3 - Layout"), isModelType: false),
            ])
        defer { try? FileManager.default.removeItem(at: masterURL) }
        let jobURL = try writeDrawingFixture()
        defer { try? FileManager.default.removeItem(at: jobURL) }
        let provider: (String) -> PublishDrawingMetadata? = {
            try? PublishMetadataInspector.readFile(atPath: $0)
        }
        let dir = FileManager.default.temporaryDirectory
            .appendingPathComponent("dsdcli-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        let dsdURL = dir.appendingPathComponent("sheets.dsd")
        let dsdText = """
            [Job]
            PublishTo=PlotterNamed
            FileType=Multi
            Naming=Auto
            OutputDir=\(dir.path)
            [Sheet1]
            Source=\(jobURL.path)
            Tab=Model
            Space=Model
            Name=1-Model
            AssignMode=Imported
            SetupName=PDF A4 - Model
            MasterPath=\(masterURL.path)
            [Sheet2]
            Source=\(masterURL.path)
            Tab=Layout1
            Space=Layout
            Name=Master-Layout1
            """
        try dsdText.write(to: dsdURL, atomically: true, encoding: .utf8)

        // Load from disk, then resolve against real drawing metadata.
        let job = try PublishCLIRun.loadJob(atPath: dsdURL.path)
        XCTAssertEqual(job.sheets.count, 2)
        let resolved = PublishCLIRun.resolveSpec(job: job, metadataProvider: provider)
        XCTAssertEqual(resolved.unresolved, 0)
        XCTAssertEqual(resolved.spec.sheets.map(\.sheetName), ["1-Model", "Master-Layout1"])
        let borrowed = try XCTUnwrap(resolved.spec.sheets.first)
        XCTAssertEqual(borrowed.assignment.mode, .importedMaster)
        XCTAssertEqual(borrowed.assignment.masterDwgPath, masterURL.path)
        XCTAssertEqual(borrowed.resolvedSetup?.plotConfigName, "DWG To PDF.pc3")
        XCTAssertEqual(resolved.spec.outputDirectory, dir.path)
        XCTAssertEqual(resolved.spec.namingPolicy, .autoName)

        // Missing drawings still list from stubs (honest preflight later).
        let stubbed = PublishCLIRun.resolveSpec(job: job, metadataProvider: { _ in nil })
        XCTAssertEqual(stubbed.spec.sheets.count, 2)
        XCTAssertEqual(stubbed.unresolved, 1, "the Master import cannot resolve without files")

        // Append mode keeps existing rows and de-dupes names.
        var store = PublishSheetStore()
        XCTAssertEqual(store.applyDSDJob(job, mode: .append, metadataProvider: provider), 0)
        XCTAssertEqual(store.applyDSDJob(job, mode: .append, metadataProvider: provider), 0)
        XCTAssertEqual(store.sheets.count, 4)
        XCTAssertEqual(Set(store.sheets.map(\.sheetName)).count, 4)
        XCTAssertTrue(store.sheets.map(\.sheetName).contains("1-Model (2)"))

        // Replace mode restores exactly the loaded rows.
        XCTAssertEqual(store.applyDSDJob(job, mode: .replace, metadataProvider: provider), 0)
        XCTAssertEqual(store.sheets.count, 2)
    }

    func testLoadJobMissingFileThrows() {
        XCTAssertThrowsError(try PublishCLIRun.loadJob(
            atPath: "/no/such/sheets-\(UUID().uuidString).dsd"))
    }

    // MARK: - Foreground run + CSV log creation

    func testForegroundRunWritesLogBesideDSD() async throws {
        let drawingID = UUID()
        let meta = PublishDrawingMetadata(
            sourcePath: "/jobs/1.dxf",
            displayName: "1.dxf",
            tabs: [
                PublishDrawingTabMetadata(
                    name: "Model", space: .model,
                    defaultSetupName: "S",
                    defaultSetup: modelSetup(named: "S")),
                PublishDrawingTabMetadata(
                    name: "Layout1", space: .layout,
                    defaultSetupName: "S",
                    defaultSetup: layoutSetup(named: "S")),
            ])
        let snaps = ["Model": snapshotDoc().snapshot(), "Layout1": snapshotDoc().snapshot()]
        let dir = FileManager.default.temporaryDirectory
            .appendingPathComponent("dsdcli-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        let dsdPath = dir.appendingPathComponent("job.dsd").path
        let dsdText = """
            [Job]
            PublishTo=PDF
            FileType=Single
            Naming=Auto
            OutputDir=\(dir.path)
            [Sheet1]
            Source=/jobs/1.dxf
            Tab=Model
            Space=Model
            Name=1-Model
            [Sheet2]
            Source=/jobs/1.dxf
            Tab=Layout1
            Space=Layout
            Name=1-Layout1
            """

        let (report, logURL) = try await PublishCLIRun.runForeground(
            dsdPath: dsdPath,
            openDrawings: [drawingID: snaps],
            readFile: { _ in dsdText },
            metadataProvider: { path in
                XCTAssertEqual(path, "/jobs/1.dxf")
                return meta
            })
        // openDrawings short-circuit disk: the canned id must win.
        XCTAssertEqual(report.outputURLs.count, 0, "canned id differs from resolved ids")
        XCTAssertTrue(report.sheets.allSatisfy { $0.status == .error })
        // The log still records every row beside the `.dsd`.
        XCTAssertEqual(logURL, PublishDSDLog.logURL(besideDSDPath: dsdPath))
        XCTAssertTrue(FileManager.default.fileExists(atPath: logURL.path))
        let log = try String(contentsOf: logURL, encoding: .utf8)
        let rows = log.components(separatedBy: CharacterSet.newlines)
            .filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }
        XCTAssertEqual(rows.count, 3, "header + one row per sheet, got:\n\(log)")
        XCTAssertTrue(rows[0].hasPrefix("Sheet,Source,Tab,Space,Setup,Status,Message,Output"))
        XCTAssertTrue(log.contains("1-Model"))
        XCTAssertTrue(log.contains("1-Layout1"))
        XCTAssertTrue(log.contains("error"))
    }

    func testForegroundRunUsesMatchingOpenDrawings() async throws {
        let metaID = UUID()
        let meta = PublishDrawingMetadata(
            id: metaID,
            sourcePath: "/jobs/1.dxf",
            displayName: "1.dxf",
            tabs: [
                PublishDrawingTabMetadata(
                    name: "Model", space: .model,
                    defaultSetupName: "S",
                    defaultSetup: modelSetup(named: "S")),
                PublishDrawingTabMetadata(
                    name: "Layout1", space: .layout,
                    defaultSetupName: "S",
                    defaultSetup: layoutSetup(named: "S")),
            ])
        let snaps = ["Model": snapshotDoc().snapshot(), "Layout1": snapshotDoc().snapshot()]
        let dir = FileManager.default.temporaryDirectory
            .appendingPathComponent("dsdcli-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        let dsdPath = dir.appendingPathComponent("job.dsd").path
        let dsdText = """
            [Job]
            PublishTo=PDF
            FileType=Single
            Naming=Auto
            OutputDir=\(dir.path)
            [Sheet1]
            Source=/jobs/1.dxf
            Tab=Model
            Space=Model
            Name=1-Model
            [Sheet2]
            Source=/jobs/1.dxf
            Tab=Layout1
            Space=Layout
            Name=1-Layout1
            """
        let (report, logURL) = try await PublishCLIRun.runForeground(
            dsdPath: dsdPath,
            openDrawings: [metaID: snaps],
            readFile: { _ in dsdText },
            metadataProvider: { _ in meta })
        XCTAssertEqual(report.outputURLs.count, 2)
        XCTAssertTrue(report.sheets.allSatisfy { $0.status == .ready })
        let log = try String(contentsOf: logURL, encoding: .utf8)
        XCTAssertTrue(log.contains("ready"))
        XCTAssertEqual(logURL.deletingLastPathComponent().path, dir.path)
    }

    func testCSVQuoting() {
        var report = PublishJobReport()
        let id = UUID()
        report.sheets = [PublishSheetReport(
            id: id, sheetName: "A, \"B\"", status: .ready, message: "ok")]
        var spec = PublishJobSpec(sheets: [PublishSheetEntry(
            sheetName: "A, \"B\"", drawingID: UUID(), sourceDwgPath: "/x/y.dxf",
            tabName: "Model", space: .model)])
        spec.sheets[0].id = id
        let text = PublishDSDLog.csvText(report: report, spec: spec)
        XCTAssertTrue(text.contains("\"A, \"\"B\"\"\""), "comma/quote fields quote, got:\n\(text)")
        XCTAssertEqual(
            PublishDSDLog.logURL(besideDSDPath: "/jobs/out/job.dsd").path,
            URL(fileURLWithPath: "/jobs/out/job-publish-log.csv").path)
    }

    // MARK: - `-PUBLISH` prompt flow

    private final class SessionHarness: @unchecked Sendable {
        var lines: [String] = []
        var finished = false
        var published: [(spec: PublishJobSpec, path: String)] = []
    }

    private func sessionContext(
        harness: SessionHarness, dsdText: String, report: PublishJobReport, logURL: URL?
    ) -> PublishCliContext {
        PublishCliContext(
            printLine: { [weak harness] in harness?.lines.append($0) },
            readTextFile: { path in
                guard path == "/jobs/sheets.dsd" else {
                    throw NSError(
                        domain: NSCocoaErrorDomain, code: NSFileReadNoSuchFileError,
                        userInfo: [NSLocalizedDescriptionKey: "File not found: \(path)"])
                }
                return dsdText
            },
            metadataProvider: { _ in nil },
            publish: { [weak harness] spec, path, completion in
                harness?.published.append((spec, path))
                completion(report, logURL)
            },
            onFinish: { [weak harness] in harness?.finished = true })
    }

    func testPublishSessionPromptsAndRuns() throws {
        let harness = SessionHarness()
        let report = PublishJobReport(
            sheets: [PublishSheetReport(
                id: UUID(), sheetName: "1-Model", status: .ready,
                message: "Published to 1-Model.pdf.")],
            outputURLs: [URL(fileURLWithPath: "/jobs/out/1-Model.pdf")])
        let logURL = URL(fileURLWithPath: "/jobs/sheets-publish-log.csv")
        let dsdText = """
            [Job]
            PublishTo=PDF
            FileType=Single
            Naming=Auto
            OutputDir=/jobs/out
            [Sheet1]
            Source=/jobs/1.dxf
            Tab=Model
            Space=Model
            Name=1-Model
            """
        let ctx = sessionContext(harness: harness, dsdText: dsdText, report: report, logURL: logURL)
        let session = PublishCliSession.start(ctx: ctx)
        XCTAssertEqual(session.currentPrompt(ctx: ctx), "Enter sheet list (.dsd) file name:")

        session.handle("", ctx: ctx) // bare Enter re-prompts
        XCTAssertFalse(harness.finished)

        session.handle("/jobs/missing.dsd", ctx: ctx) // unreadable retries
        XCTAssertFalse(harness.finished)
        XCTAssertTrue(harness.lines.joined().contains("Load failed"))

        session.handle("/jobs/sheets.dsd", ctx: ctx) // loads, publishes, finishes
        XCTAssertTrue(harness.finished)
        XCTAssertEqual(harness.published.count, 1)
        XCTAssertEqual(harness.published[0].path, "/jobs/sheets.dsd")
        XCTAssertEqual(harness.published[0].spec.sheets.map(\.sheetName), ["1-Model"])
        let joined = harness.lines.joined(separator: "\n")
        XCTAssertTrue(joined.contains("Loaded 1 sheets from sheets.dsd."))
        XCTAssertTrue(joined.contains("Published 1/1 sheets to /jobs/out/1-Model.pdf."))
        XCTAssertTrue(joined.contains("Log: /jobs/sheets-publish-log.csv."))
    }

    func testPublishSessionEmptyListRetries() {
        let harness = SessionHarness()
        let ctx = sessionContext(
            harness: harness, dsdText: "[Job]\nPublishTo=PDF\n",
            report: PublishJobReport(), logURL: nil)
        let session = PublishCliSession.start(ctx: ctx)
        session.handle("/jobs/sheets.dsd", ctx: ctx)
        XCTAssertFalse(harness.finished)
        XCTAssertTrue(harness.lines.joined().contains("No sheets"))
        XCTAssertTrue(harness.published.isEmpty)
    }
}
